function switchInstView(v){
var showS=v==='scholars';
var mb=document.getElementById('instMapBlock');
var rt=document.getElementById('instRegionTabs');
var tt=document.getElementById('instTypeTabs');
var ig=document.getElementById('instg');
var cp=document.getElementById('univCatalogPanel');
if(mb)mb.style.display=showS?'':'none';
if(rt&&rt.parentElement)rt.parentElement.style.display=showS?'':'none';
if(tt&&tt.parentElement)tt.parentElement.style.display=showS?'':'none';
if(ig)ig.style.display=showS?'':'none';
if(cp){cp.style.display=showS?'none':'block';
  if(!showS&&!cp.dataset.rendered){renderUnivCatalog();cp.dataset.rendered='1';}
}
['ivt-scholars','ivt-catalog'].forEach(function(id){
  var b=document.getElementById(id);if(!b)return;
  var on=id==='ivt-'+v;
  b.style.background=on?'rgba(46,154,137,.15)':'transparent';
  b.style.color=on?'#2E9A89':'#8A94A8';
  b.style.fontWeight=on?'700':'500';
});
if(!showS){
  var vw=document.getElementById('vw-institutions');
  if(vw){setTimeout(function(){vw.scrollIntoView({behavior:'smooth',block:'start'});setTimeout(function(){window.scrollBy(0,-80);},300);},60);}
}
}
function setUcFilter(tp){
window._ucTp=tp;
['all','985','211','双一流','url'].forEach(function(k){
  var b=document.getElementById('ucf-'+k);if(!b)return;
  var on=k===tp;
  b.style.background=on?'rgba(46,154,137,.12)':'rgba(255,255,255,.04)';
  b.style.borderColor=on?'rgba(46,154,137,.3)':'rgba(255,255,255,.09)';
  b.style.color=on?'#2E9A89':'#8A94A8';
});
var s=document.getElementById('ucSearch');
filterCatalog(s?s.value:'',tp);
}
function filterCatalog(q,tp){
q=(q||'').trim().toLowerCase();
tp=tp||window._ucTp||'all';
var total=0,shown=0;
document.querySelectorAll('.uc-card').forEach(function(c){
  var nm=(c.dataset.n||'').toLowerCase();
  var pv=(c.dataset.prov||'').toLowerCase();
  var ctp=c.dataset.tp||'';
  var hasUrl=c.dataset.url==='1';
  var matchQ=!q||nm.indexOf(q)>=0||pv.indexOf(q)>=0;
  var matchTp=tp==='all'||ctp===tp||(tp==='url'&&hasUrl);
  total++;
  if(matchQ&&matchTp){c.style.display='';shown++;}
  else{c.style.display='none';}
});
document.querySelectorAll('.uc-region').forEach(function(r){
  var cards=Array.from(r.querySelectorAll('.uc-card'));
  var vis=cards.filter(function(c){return c.style.display!=='none';});
  r.style.display=vis.length?'':'none';
  var ce=r.querySelector('.uc-reg-cnt');if(ce)ce.textContent=vis.length+' 所';
});
var rc=document.getElementById('ucResultCount');
if(rc)rc.textContent=shown<total?'找到 '+shown+' 所':'共 '+total+' 所院校';
}
