  renderGSR=function(qv){
    var list=document.getElementById('gsrList');
    var empty=document.getElementById('gsrEmpty');
    if(!list)return;
    var scholars=typeof S!=='undefined'?S:[];
    if(!qv||qv.length<1){
      var hot=scholars.filter(function(s){return (s.hats&&s.hats.length)||(s.hon&&s.hon.length);}).slice(0,8);
      _gsr_results=hot;_gsr_idx=-1;
      var hotTerms=["北体大 长江","运动心理学","青年 优青","博士生导师","运动康复","华东师大","体育管理"];
      list.innerHTML='<div class="gsr-hot"><div class="gsr-hot-title">热门组合检索</div><div class="gsr-hot-row">'+hotTerms.map(function(t){return '<button onclick="cssdApplySearchPreset(this.textContent)">'+t+'</button>';}).join('')+'</div></div>'+hot.map(function(s,i){return gsrItem(s,i,'');}).join('');
      if(empty)empty.style.display='none';
      return;
    }
    var ranked=scholars.map(function(s){var r=cssdSearchRank(s,qv);return {s:s,r:r};}).filter(function(x){return x.r.ok;}).sort(function(a,b){return b.r.score-a.r.score;}).slice(0,12);
    _gsr_results=ranked.map(function(x){x.s._cssdReason=x.r.reason;x.s._cssdScore=x.r.score;return x.s;});
    _gsr_idx=-1;
    if(!ranked.length){
      list.innerHTML='';
      if(empty)empty.style.display='block';
    }else{
      if(empty)empty.style.display='none';
      list.innerHTML=_gsr_results.map(function(s,i){return gsrItem(s,i,qv);}).join('');
    }
  };

  gsrItem=function(s,i,qv){
    var DISC_COLOR={sci:'#3E82B0',psych:'#2C6E9E',hu:'#f43f5e',train:'#f59e0b',trad:'#2C6E9E',mgmt:'#10b981',rehab:'#f97316',pe:'#3b82f6',eng:'#ec4899',outdoor:'#3FB39C'};
    var dc=DISC_COLOR[s.disc]||'#64748b';
    var name=s.n;
    if(qv){
      var qt=cssdExpandQuery(qv).tokens[0]||qv;
      try{name=s.n.replace(new RegExp(qt.replace(/[.*+?^$()|[\]\\]/g,'\\$&'),'g'),'<mark>'+qt+'</mark>');}catch(e){}
    }
    var hat=s.hats&&s.hats.length?s.hats[0]:'';
    var reason=s._cssdReason||'智能检索匹配';
    var score=s._cssdScore?'<div class="gsr-score">'+Math.round(s._cssdScore)+'</div>':'';
    return '<div class="gsr-item" data-idx="'+i+'" onmouseenter="_gsr_idx='+i+';updateGSRActive()" onclick="gsrOpen('+i+')">'+
      '<div class="gsr-av" style="background:'+s.c+'22;color:'+s.c+'">'+s.i+'</div>'+
      '<div style="flex:1;min-width:0"><div class="gsr-name">'+name+'</div><div class="gsr-sub">'+s.s+(hat?' · ⭐ '+hat:'')+'</div><div class="gsr-reason">'+reason+'</div></div>'+
      '<div><div class="gsr-disc-tag" style="background:'+dc+'15;color:'+dc+';border:1px solid '+dc+'25;">'+s.dL+'</div>'+score+'</div>'+
    '</div>';
  };

  function cssdAttr(v){return String(v||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');}
  function sdTags(s){
    return '<span class="tag '+(DC[s.disc]||'')+'">'+s.dL+'</span>'+
      (s.hats||[]).map(function(h){return '<span class="tag t-hat">'+hS(h)+'</span>';}).join('')+
      (s.hon||[]).slice(0,2).map(function(h){return '<span class="tag t-honor" style="font-size:.7rem">'+(h.length>18?h.slice(0,18)+'…':h)+'</span>';}).join('');
  }
  function sdRelated(s){
    var peers=S.filter(function(x){return x.id!==s.id&&(x.disc===s.disc||x.institution===s.institution);})
      .map(function(x){var score=(x.disc===s.disc?3:0)+(x.institution===s.institution?4:0)+((x.hats||[]).length?1:0);return {x:x,score:score};})
      .sort(function(a,b){return b.score-a.score;}).slice(0,5).map(function(o){return o.x;});
    if(!peers.length)return '<div class="sd-text" style="color:#64748b">暂无相近学者</div>';
    return peers.map(function(p){return '<button onclick="openCardById('+p.id+')"><span class="sd-mini-av" style="background:'+p.c+'22;color:'+p.c+'">'+p.i+'</span><span style="min-width:0"><b>'+p.n+'</b><small>'+p.s+' · '+p.dL+'</small></span></button>';}).join('');
  }
  function sdStrength(s){
    var talent=Math.min(100,((s.hats||[]).length*28+(s.hon||[]).length*12)+(s.role?12:0));
    var inst=S.filter(function(x){return x.institution===s.institution;}).length;
    var instScore=Math.min(100,Math.round(inst/Math.max(1,S.length)*900));
    var field=S.filter(function(x){return x.disc===s.disc;}).length;
    var fieldScore=Math.min(100,Math.round(field/Math.max(1,S.length)*600));
    return [
      ['人才项目',talent||18],
      ['机构队伍',instScore||20],
      ['学科覆盖',fieldScore||20]
    ].map(function(m){return '<div class="sd-meter-row"><span>'+m[0]+'</span><div class="sd-meter-track"><div class="sd-meter-fill" style="width:'+m[1]+'%"></div></div><b>'+m[1]+'</b></div>';}).join('');
  }
  function sdTimeline(s){
    var items=[
      ['当前','任职于 '+s.institution+(s.dept?' · '+s.dept:'')],
      ['方向','主要研究：'+s.r],
      ['学科','归入 '+s.dL+' 方向'],
    ];
    if((s.hats||[]).length)items.push(['人才',s.hats.join(' · ')]);
    if(s.role)items.push(['治理',RL[s.role]||s.role]);
    return items.map(function(it){return '<div class="sd-tl-item"><div class="sd-tl-year">'+it[0]+'</div><div class="sd-tl-card">'+it[1]+'</div></div>';}).join('');
  }
